"""Write C0_SEAM RowLeaf cells for the MCB00-D driver cases.

Standard byte packing only: this never imports or runs the engine and reads no
other fixture. Layouts follow dev3-row-format (XRW1) and dev3-tree-format
(leaf cell = u16 LE key/value lengths, big-endian RowId key, value bytes).
The cells are untrusted literal input for a test-only source, not stored,
authenticated or pinned rows. Expected values are literal in the tests.
"""

from pathlib import Path
from struct import pack, pack_into

HERE = Path(__file__).parent
DATABASE = bytes([0x11]) * 16
TIMELINE = 7
EPOCH = 3


def txn_id(local):
    return DATABASE + pack("<QI4xQ", TIMELINE, EPOCH, local)


def txn_ref(local, generation):
    return txn_id(local) + pack("<Q", generation)


def undo_ref(slot):
    # PageRef(file, page_no, incarnation), slot, six zero bytes, generation.
    return pack("<QQQH6xQ", 0x0000_0001_0000_0002, 9, 2, slot, 4)


def record(row, value, local, mutation, committed=None, txn=None, undo=None):
    body = pack("<IBq", 1, 2, value)  # one Int64 column
    header = bytearray(168)
    header[0:4] = b"XRW1"
    pack_into("<HBBQ", header, 4, 1, 0 if undo is None else 2, 1, row)
    if committed is not None:
        header[16] = 1
        pack_into("<Q", header, 24, committed)
    else:
        header[16] = 2
        header[24:72] = txn_ref(*txn)
    header[72:112] = txn_id(local)
    pack_into("<Q", header, 112, mutation)
    if undo is not None:
        header[120:160] = undo_ref(undo)
    pack_into("<I", header, 160, len(body))
    return bytes(header) + body


def cell(row, value, **version):
    data = record(row, value, **version)
    return pack("<HH", 8, len(data)) + row.to_bytes(8, "big") + data


CELLS = {
    "r05": cell(5, 50, local=1, mutation=2, committed=2),
    "r10": cell(10, 100, local=4, mutation=1, committed=12, undo=1),
    "r15": cell(15, 150, local=11, mutation=1, txn=(11, 6), undo=4),
    "r20": cell(20, 200, local=9, mutation=1, txn=(9, 5), undo=2),
    "r25": cell(25, 250, local=11, mutation=2, txn=(11, 6), undo=5),
    "r30": cell(30, 300, local=2, mutation=1, committed=5),
    "r40": cell(40, 400, local=1, mutation=1, committed=3),
}
LEAVES = {
    "leaf_a": "r10 r20 r30 r40",
    "leaf_b": "r05 r10 r15 r20 r25 r30 r40",
    "leaf_c": "r10 r40",
}

if __name__ == "__main__":
    lines = [
        "# C0_SEAM: independent RowLeaf cells; not stored, authenticated or pinned rows.",
        "# DB=11x16; timeline=7; epoch=3; one Int64 column; undo file=0x100000002 page=9 inc=2 gen=4.",
        "# r05 c2; r10 c12+U1; r15 txn11/g6+U4; r20 txn9/g5+U2; r25 txn11/g6+U5; r30 c5; r40 c3.",
        "# Generated by make_driver_cells.py; expected results are literal in driver/tests.rs.",
    ]
    lines += [f"{name}={data.hex()}" for name, data in CELLS.items()]
    lines += [f"{name}={rows}" for name, rows in LEAVES.items()]
    (HERE / "driver-cells.txt").write_text("\n".join(lines) + "\n")
